import{_ as t,o,c as r,j as a,a as s}from"./chunks/framework.DdpBa4_E.js";const f=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"books/attached/35-一谈恋爱就遇到麻烦.md","filePath":"books/attached/35-一谈恋爱就遇到麻烦.md","lastUpdated":1794316978000}'),n={name:"books/attached/35-一谈恋爱就遇到麻烦.md"};function d(l,e,_,c,i,p){return o(),r("div",null,[...e[0]||(e[0]=[a("h3",{id:"一谈恋爱就遇到麻烦",tabindex:"-1"},[s("一谈恋爱就遇到麻烦 "),a("a",{class:"header-anchor",href:"#一谈恋爱就遇到麻烦","aria-label":'Permalink to "一谈恋爱就遇到麻烦"'},"​")],-1),a("p",null,"当艾米莉还是个精神病学实习生时，她就立志成为一名精神分析师。在精神分析学院的课程开始之前，她应要求需要接受为期至少一年的个人分析，每周要进行四次治疗，也就是躺在诊疗椅上，畅谈脑中所想。开始时，艾米莉表现得很不错。事实上，她的表现可以说非常完美，以至于她的分析师认为，顶多两年她就能完成分析——这可是前所未有的，通常来说精神分析至少需要做四到五年。",-1),a("p",null,"而后她与大卫（David）相遇了，并且迅速迷恋上了他。大卫是名颇有抱负的演员，事实证明这可不算件好事。他抛出了各种求爱暗示，也的确让艾米莉心潮激荡。我曾同艾米莉一起在中央公园绕着水库跑步，当时她的工作寻呼机和手机寸步不离身。（那个时代的手机可是很大很重的！）她会每隔几分钟，就轮流翻一遍寻呼机和手机，就怕错过打进来的电话。在工作中，她也要花上几个小时，使用在当时还很新颖的因特网，去追踪大卫的动向。比如，她会注册一个假网名，然后在聊天室与他频频聊天。简单来说，她就是变得有点不可自拔了。",-1),a("p",null,"她的分析师完全没法想象，这种可怕的转变会发生在他最有希望的案主身上。艾米莉渐渐从一个适应力极强、十分独立自主的人，开始变为一个带有“边缘性受虐狂人格特质”的人。这样看来，她的分析尚需再多做几年了。",-1)])])}const h=t(n,[["render",d]]);export{f as __pageData,h as default};
